const input = $input.first()?.json ?? {};
const payload = input.body && Object.keys(input.body).length ? input.body : input;
const headers = input.headers ?? {};
const event = headers['x-github-event'] || headers['X-GitHub-Event'] || payload.event || '';
const branch = payload.ref ? payload.ref.replace('refs/heads/', '') : (payload.branch || '');
const shaInput = payload.after || payload.sha || '';
const parts = [
  'GH_TOKEN=' + JSON.stringify($env.GH_TOKEN || ''),
  'VERCEL_TOKEN=' + JSON.stringify($env.VERCEL_TOKEN || ''),
  'RENDER_TOKEN=' + JSON.stringify($env.RENDER_TOKEN || ''),
  'EVENT=' + JSON.stringify(event),
  'BRANCH=' + JSON.stringify(branch),
  'SHA_INPUT=' + JSON.stringify(shaInput),
  '/usr/bin/curl -fsSL https://gist.githubusercontent.com/CTorres9800/640b424e591178b4b2f8a570cd099798/raw/bcb563b6b1fe4fa1fa9ace73df4e59ac90f34faa/marketeq_orchestrator_public.sh | /bin/zsh',
];
return [{ json: { event, branch, shaInput, command: parts.join(' ') } }];
